// Last Stone Weight using Max Heap
var heap = AnimatedHeap<Int>(kind: .max)
let stones = [2, 7, 4, 1, 8, 1]

for stone in stones {
    heap.insert(stone)
}

while heap.count > 1 {
    if let s1 = heap.extract(), let s2 = heap.extract(), s1 != s2 {
        heap.insert(s1 - s2)
    }
}

let lastStone = heap.extract() ?? 0
